    const fetchLocations = async () => {
      try {
        const res = await axios.get("/Filter.json");
        if (Array.isArray(res.data)) {
          allLocationsRef.current = res.data;
          // Pre-load a few for default options
          const initialOptions = res.data.slice(0, 50).map((loc) => ({
            value: loc,
            label: loc,
          }));
          setLocationOptions(initialOptions);
        }
      } catch (error) {
        console.error("Failed to fetch locations:", error);
      }
    };
    fetchLocations();
