  const filterLocations = (inputValue) => {
    if (!inputValue) {
      return allLocationsRef.current.slice(0, 50).map((loc) => ({
        value: loc,
        label: loc,
      }));
    }
    const search = inputValue.toLowerCase();
    const filtered = [];
    for (const loc of allLocationsRef.current) {
      if (loc.toLowerCase().includes(search)) {
        filtered.push({ value: loc, label: loc });
        if (filtered.length >= 50) break; // Optimization: stop after 50 matches
      }
    }
    return filtered;
  };

  const promiseOptions = (inputValue) =>
    new Promise((resolve) => {
      setTimeout(() => {
        resolve(filterLocations(inputValue));
      }, 300);
    });

  // NEW: Modified handleFileChange to show cropper for logo
  const handleFileChange = (e) => {
    const file = e.target.files[0];

    // Do nothing if no file is selected (user cancels the dialog)
    if (!file) return;

    const allowedTypes = ["image/png", "image/jpg", "image/jpeg"];
    if (!allowedTypes.includes(file.type)) {
      toast.error("Invalid file format. Please upload PNG or JPG image.");
      e.target.value = ""; // Reset input so user can try again
      return;
    }

    const reader = new FileReader();
    reader.onload = (event) => {
      setImageToCrop(event.target.result);

      // Determine what we're cropping
      if (e.target.id === "coverUpload") {
        setCroppingType("cover"); // Set to cover
      } else if (e.target.id === "logoUpload") {
        setCroppingType("logo"); // Set to logo
      }

      setShowCropper(true);
      setCrop({ x: 0, y: 0 });
      setZoom(1);
    };
    reader.readAsDataURL(file);
  };

  // NEW: Function to create cropped image
  const createImage = (url) =>
    new Promise((resolve, reject) => {
      const image = new Image();
      image.addEventListener("load", () => resolve(image));
      image.addEventListener("error", (error) => reject(error));
      image.setAttribute("crossOrigin", "anonymous");
      image.src = url;
    });

  // NEW: Function to get cropped image
  const getCroppedImg = async (imageSrc, pixelCrop) => {
    const image = await createImage(imageSrc);
    const canvas = document.createElement("canvas");
    const ctx = canvas.getContext("2d");

    if (!ctx) {
      return null;
    }

    // Set canvas size based on cropping type
    if (croppingType === "logo") {
      // Logo: 226x226
      canvas.width = 226;
      canvas.height = 226;
    } else {
      // Cover: 762x300
      canvas.width = 762;
      canvas.height = 300;
    }

    // Calculate the scale between the displayed image and the actual image
    const scaleX = image.naturalWidth / image.width;
    const scaleY = image.naturalHeight / image.height;

    // Draw the cropped image, scaling to fit the desired output dimensions
    ctx.drawImage(
      image,
      pixelCrop.x * scaleX,
      pixelCrop.y * scaleY,
      pixelCrop.width * scaleX,
      pixelCrop.height * scaleY,
      0,
      0,
      canvas.width,
      canvas.height,
    );

    return new Promise((resolve) => {
      canvas.toBlob(
        (blob) => {
          if (!blob) {
            console.error("Canvas is empty");
            return;
          }
          resolve(blob);
        },
        "image/jpeg",
        0.9,
      ); // 90% quality
    });
  };

