  const handleSubmit = async (e) => {
    e.preventDefault();

    if (logoImage === DEFAULT_LOGO || !values.logo) {
      alert("Please upload a logo before submitting!");
      return;
    }
    if (coverImage === DEFAULT_COVER || !values.banner) {
      alert("Please upload a banner before submitting!");
      return;
    }

    // --- Document validation ---
    const hasAtLeastOneDocument = values.documents.some(
      (doc) => doc.docType && (doc.file instanceof File || doc.docFile),
    );

    if (!hasAtLeastOneDocument) {
      toast.error(
        "At least one document (type + file) is required to get approved",
      );
      return;
    }

    // Check if any document has file but no docType
    const hasFileWithoutDocType = values.documents.some(
      (doc) => doc.file instanceof File && !doc.docType,
    );

    if (hasFileWithoutDocType) {
      toast.error("Please select document type for all uploaded files");
      return;
    }

    // --- Authorization Document Validation ---
    const hasNewDocument =
      values.authorizedPerson?.authDocument instanceof File;
    const hasExistingDocument =
      values.authorizedPerson?.existingDocumentUrl &&
      values.authorizedPerson.existingDocumentUrl.trim() !== "";

    if (!hasNewDocument && !hasExistingDocument) {
      toast.error(
        "Authorization document is required. Please upload an authorization letter or ownership document.",
      );
      return;
    }

    // --- Validation for terms & policies ---
    const { termsAccepted, privacyAccepted, paymentAgree } = values;

    if (!termsAccepted && !privacyAccepted && !paymentAgree) {
      setErrorMessage(
        "Please Agree to the Terms & Conditions, Privacy Policy, and Payment Policy",
      );
      return;
    }
    if (!termsAccepted && !privacyAccepted) {
      setErrorMessage(
        "Please Agree to the Terms & Conditions and Privacy Policy",
      );
      return;
    }
    if (!termsAccepted && !paymentAgree) {
      setErrorMessage(
        "Please Agree to the Terms & Conditions and Payment Policy",
      );
      return;
    }
    if (!privacyAccepted && !paymentAgree) {
      setErrorMessage("Please Agree to the Privacy Policy and Payment Policy");
      return;
    }
    if (!termsAccepted) {
      setErrorMessage("Please Agree to the Terms & Conditions");
      return;
    }
    if (!privacyAccepted) {
      setErrorMessage("Please Agree to the Privacy Policy");
      return;
    }
    if (!paymentAgree) {
      setErrorMessage("Please Agree to the Payment Policy");
      return;
    }

    setErrorMessage("");
    // setLoading(true);

    try {
      const formData = new FormData();

      for (const [key, val] of Object.entries(values)) {
        if (key === "bankDetails" || key === "socialMedia" || key === "gallery")
          continue;

        if (key === "authorizedPerson") {
          formData.append("authPersonName", val.name);
          formData.append("authPersonDesignation", val.designation);

          // FIX: Always send the existing document URL if no new file is uploaded
          if (val.authDocument instanceof File) {
            formData.append("authDocument", val.authDocument);
          } else if (val.existingDocumentUrl) {
            // Send the existing document URL to preserve it
            formData.append("existingAuthDocumentUrl", val.existingDocumentUrl);
          }
        } else if (
          key === "availableFacilities" ||
          key === "availableInsurance" ||
          key === "freeSampleLocations"
        ) {
          formData.append(key, JSON.stringify(val));
        } else if (key === "documents") {
          const newDocs = [];
          const existingDocs = [];

          for (let index = 0; index < val.length; index++) {
            const doc = val[index];

            if (doc.file instanceof File) {
              const inputElement =
                document.querySelectorAll('input[type="file"]')[index];
              const acceptFormats = inputElement.accept.split(",");
              const fileName = doc.file.name.toLowerCase();
              const isValid = acceptFormats.some((ext) =>
                fileName.endsWith(ext.trim()),
              );

              newDocs.push(doc);
              formData.append("documents", doc.file);
            } else if (doc.docFile) {
              existingDocs.push({
                docType: doc.docType,
                docFile: doc.docFile,
                _id: doc._id || null,
              });
            }
          }

          if (newDocs.length > 0) {
            const docTypesArray = newDocs.map((doc) => doc.docType);
            formData.append("docTypes", JSON.stringify(docTypesArray));
          }

          if (existingDocs.length > 0) {
            formData.append("existingDocuments", JSON.stringify(existingDocs));
          }
        } else if (key === "multiplePhoneNumbers") {
          formData.append("multiplePhoneNumbers", JSON.stringify(val));
        } else if (key === "logo" || key === "banner") {
          if (val instanceof File) {
            formData.append(key, val);
          }
        } else {
          formData.append(key, val);
        }
      }

      // API Request
      const res = await axios.put(
        `${process.env.REACT_APP_BACKEND_URL}/api/centres/${centreId}`,
        formData,
        { headers: { "Content-Type": "multipart/form-data" } },
      );

      if (res.status === 200) {
        toast.success("Centre profile updated successfully");

        // Wait for toast to show, then refresh page to show updated content
        setTimeout(() => {
          window.location.reload(); // This will refresh and show the updated authorized document
        }, 1500);
      }
    } catch (error) {
      console.error("Error updating centre:", error);
      toast.error(error.response?.data?.message || "Update failed");
      // setLoading(false);
    }
  };

